def running_max(numbers):
    """Return the running maximum: element i is max(numbers[0..i])."""
    if not numbers:
        return []
    out = [numbers[0]]
    best = numbers[0]
    for x in numbers[1:]:
        best = max(best, x)
        out.append(best)
    return out

